    obstacles = set(map(tuple, observation.get("obstacles", []) or []))

    def inb(x, y):
        return 0 <= x < w and 0 <= y < h

    def neighbors(nx, ny):
        res = []
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                x, y = nx + dx, ny + dy
                if inb(x, y) and (x, y) not in obstacles:
                    res.append((dx, dy))
        return res

